-- Projets reels, tires des depots GitHub de mysteriodataweb (28 projets).
-- A executer une fois dans l'editeur SQL de Supabase. Le script peut etre relance sans risque.
--
-- 1. Recale les compteurs d'id (sinon creer un projet ou un article depuis l'admin echoue).
-- 2. Supprime les 6 projets fictifs.
-- 3. Ajoute ou met a jour les projets reels (cle : slug). Une image deja envoyee depuis l'admin
--    (URL Supabase) est conservee ; sinon le projet recoit sa couverture /images/projects/<slug>.svg
--    (fichiers du frontend).

BEGIN;

-- Bases creees par une ancienne version de db:init : colonnes d'archivage absentes.
ALTER TABLE projects ADD COLUMN IF NOT EXISTS archived BOOLEAN DEFAULT false;
ALTER TABLE projects ADD COLUMN IF NOT EXISTS archived_at TIMESTAMP;

-- migrate-supabase.sql insere des id explicites sans recaler les compteurs : la ligne suivante
-- (ici ou depuis l'admin) tombait sur un id deja pris. On recale chaque table importee.
DO $$
DECLARE t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['projects', 'blog_posts', 'skill_categories', 'skills', 'certifications', 'tools', 'profile', 'messages', 'cv_sections', 'cv_items'] LOOP
    IF to_regclass(t) IS NOT NULL AND pg_get_serial_sequence(t, 'id') IS NOT NULL THEN
      EXECUTE format('SELECT setval(%L, COALESCE((SELECT MAX(id) FROM %I), 0) + 1, false)', pg_get_serial_sequence(t, 'id'), t);
    END IF;
  END LOOP;
END $$;

DELETE FROM projects WHERE slug IN ('prediction-churn-ml', 'ecommerce-platform', 'chatbot-ia-support', 'dashboard-analytics-temps-reel', 'nlp-analyse-sentiment', 'task-management-app');

-- Le slug annoncait 11 projets, le depot en contient 10.
UPDATE projects SET slug = 'ml-portfolio-projets'
WHERE slug = 'ml-portfolio-11-projects'
  AND NOT EXISTS (SELECT 1 FROM projects WHERE slug = 'ml-portfolio-projets');

INSERT INTO projects (slug, title, category, short_description, full_description, image, tech_stack, github_url, demo_url, date, featured, published, context, approach, results, challenges)
VALUES
('watertracker-afrique', 'WaterTracker Africa : suivi des retenues d''eau par satellite', 'data-engineering', 'Suivi mensuel de 96 retenues d''eau autour de Ouagadougou par imagerie satellite, avec prévision de leur remplissage à 1-3 mois.', 'Un pipeline mesure chaque mois la surface en eau de 96 retenues à partir de Sentinel-2 et Sentinel-1, prévoit leur taux de remplissage à 1-3 mois avec un intervalle de confiance, et publie un bulletin de risque consultable sur une carte interactive.', '/images/projects/watertracker-afrique.svg', '["Python", "Google Earth Engine", "Sentinel-1/2", "scikit-learn", "Prophet", "FastAPI", "PostgreSQL", "PostGIS", "APScheduler", "LLM (Groq)", "React", "TypeScript", "Leaflet"]'::jsonb, 'https://github.com/mysteriodataweb/waterTrack', NULL, '2026-10', true, true, 'Autour de Ouagadougou, les petites retenues d''eau font vivre l''agriculture et l''élevage, mais elles s''assèchent pendant la saison sèche. Les relevés de terrain sont rares : il faut un suivi régulier et une alerte avant que le niveau devienne critique.', 'Collecte automatique avec Google Earth Engine (Sentinel-2 à 10 m fusionné avec le radar Sentinel-1, pluie CHIRPS, climat ERA5-Land), stockage PostgreSQL/PostGIS, modèles scikit-learn validés dans le temps avec un intervalle à 80 % (perte quantile), Prophet pour estimer la date d''assèchement et recommandations rédigées par un LLM. L''API FastAPI est planifiée avec APScheduler ; l''interface React affiche une carte Leaflet.', 'Un bulletin mensuel classe les 96 retenues par niveau de risque, avec le remplissage mesuré, la prévision à 1-3 mois, la probabilité d''atteindre le niveau critique et un export CSV. Le notebook de recherche et le collecteur en production donnent des valeurs identiques : le pipeline est reproductible.', 'Les nuages de la saison des pluies coupent la série optique : la fusion avec le radar Sentinel-1 a permis d''obtenir une série mensuelle continue. Une prévision sans incertitude n''étant pas exploitable, chaque prédiction est livrée avec son intervalle et comparée à une prévision de référence (skill score).'),
('maintenance-predictive-kafka', 'Maintenance prédictive en streaming (NASA C-MAPSS)', 'data-engineering', 'Prédiction de la durée de vie restante de turboréacteurs, servie en temps réel par un pipeline Kafka qui publie une décision de maintenance.', 'Un modèle de régression estime à chaque cycle le nombre de cycles restants avant la défaillance d''un moteur, à partir de 26 mesures capteurs. Un pipeline Kafka ingère les mesures, calcule les variables temporelles et publie une décision : normal, inspection, surveillance renforcée ou intervention immédiate.', '/images/projects/maintenance-predictive-kafka.svg', '["Python", "pandas", "scikit-learn", "Apache Kafka", "Jupyter"]'::jsonb, 'https://github.com/mysteriodataweb/Maintenance', NULL, '2026-10', true, true, 'Réparer un moteur après la panne coûte bien plus cher que de planifier l''intervention. Le jeu de données C-MAPSS de la NASA simule la dégradation de turboréacteurs jusqu''à la défaillance.', 'Nettoyage et création de 155 variables temporelles causales, découpage par moteur (GroupShuffleSplit) pour qu''aucun moteur ne soit vu à la fois à l''entraînement et en validation, comparaison de plusieurs modèles. En production : un producer Kafka envoie les mesures, un consumer garde l''historique de chaque moteur, prédit et republie la décision sur un topic de sortie.', 'Random Forest retenu : erreur moyenne de 8,4 cycles (RMSE 11,7) sur des moteurs jamais vus à l''entraînement. Chaque prédiction devient une décision métier selon des seuils (20 cycles ou moins : intervention immédiate).', 'Le score officiel de la NASA pénalise bien plus une surestimation de la durée de vie qu''une sous-estimation, car surestimer retarde l''intervention : les seuils de décision suivent cette asymétrie. Les variables devaient rester causales pour donner le même résultat en streaming qu''en notebook.'),
('undp-sdg-classifier', 'Classification des projets du PNUD selon les 17 ODD', 'ia', 'Plateforme IA qui analyse des rapports (PDF, DOCX, TXT) et les classe selon les 17 Objectifs de développement durable.', 'Un modèle XLM-RoBERTa multilingue, affiné en classification multi-étiquettes, attribue à chaque document un score pour chacun des 17 ODD, avec les passages qui le justifient. Un assistant conversationnel répond ensuite aux questions en s''appuyant uniquement sur les documents analysés.', '/images/projects/undp-sdg-classifier.svg', '["Python", "PyTorch", "Hugging Face Transformers", "XLM-RoBERTa", "FastAPI", "Pinecone", "Gemini", "SQLite", "Next.js", "TypeScript"]'::jsonb, 'https://github.com/mysteriodataweb/undp-sdg-classifier', NULL, '2026-09', true, true, 'Les équipes du PNUD produisent de nombreux rapports de projets. Relier chacun aux Objectifs de développement durable qu''il sert se fait à la main et prend du temps.', 'Modèle XLM-RoBERTa affiné (17 sorties sigmoïdes : un document peut toucher plusieurs ODD, avec trois niveaux de confiance), API FastAPI et historique SQLite, recherche vectorielle Pinecone (embeddings all-MiniLM-L6-v2) et Gemini pour un chat ancré dans le corpus, interface Next.js 15 avec tableau de bord.', 'Une application complète : analyse d''un document avec son ODD principal, les passages de preuve, les chiffres clés et un résumé ; classement des documents par objectif ; répartition des ODD dans un tableau de bord ; chat qui cite ses sources.', 'Traiter des documents rédigés en plusieurs langues, d''où le choix de XLM-RoBERTa, et limiter les inventions du chat en l''obligeant à répondre uniquement à partir des passages fournis.'),
('ai-insurance-operations', 'AI Insurance : traitement des sinistres assisté par IA', 'ia', 'Plateforme qui automatise la saisie, le tri et l''analyse de risque des déclarations de sinistre, avec validation humaine des cas sensibles.', 'Un LLM extrait les informations d''une déclaration rédigée librement, un agent demande les éléments manquants, un moteur de règles attribue un score de risque explicable de 0 à 100, et les dossiers à risque passent obligatoirement par une validation humaine.', '/images/projects/ai-insurance-operations.svg', '["Python", "FastAPI", "SQLAlchemy", "OpenAI GPT-4o-mini", "PostgreSQL", "Supabase", "Next.js", "TypeScript", "Tailwind CSS"]'::jsonb, 'https://github.com/mysteriodataweb/ai-insurance-backend', NULL, '2026-08', true, true, 'Dans une compagnie d''assurance, chaque déclaration de sinistre arrive en texte libre et doit être relue, complétée puis évaluée avant décision : un travail répétitif et lent.', 'Backend FastAPI asynchrone (SQLAlchemy) organisé en services : extraction par GPT-4o-mini avec sorties structurées, agent de relance, moteur de risque à signaux explicables, statistiques et journal d''audit, base PostgreSQL (Supabase). Interface Next.js 14 (dépôt ai-insurance-frontend) : formulaire client, file de traitement, fiche dossier et indicateurs.', 'Une chaîne complète de la déclaration à la décision : extraction automatique, score de risque justifié, validation humaine obligatoire pour les cas à risque, traçabilité de chaque action, et tableau de bord du temps gagné et du taux d''automatisation.', 'Garder l''humain dans la boucle sans ralentir les dossiers simples, et rendre chaque score compréhensible pour un gestionnaire en affichant les signaux qui l''expliquent plutôt qu''un chiffre opaque.'),
('ai-sql-assistant', 'AI SQL Assistant : interroger une base de données en langage naturel', 'ia', 'On pose une question en français, l''assistant génère le SQL, l''exécute en lecture seule et répond en clair.', 'Le LLM reçoit le schéma de la base et génère la requête SQL, qui est validée puis exécutée en lecture seule. Il interprète ensuite le résultat et répond en langage naturel, en streaming.', '/images/projects/ai-sql-assistant.svg', '["Python", "FastAPI", "LangChain", "Ollama", "NVIDIA NIM", "SQLite", "Next.js", "TypeScript"]'::jsonb, 'https://github.com/mysteriodataweb/AI-SQL-ASSISTANT', NULL, '2026-08', false, true, 'Les équipes métier ont des questions sur leurs données mais ne parlent pas SQL : elles dépendent d''un analyste pour chaque chiffre.', 'Backend FastAPI et LangChain, validation des requêtes (SELECT et WITH uniquement), base SQLite de démonstration, réponses en streaming (SSE). Le LLM est au choix : Ollama en local (gratuit et privé) ou NVIDIA NIM pour des modèles de 70 milliards de paramètres. Interface Next.js avec historique des conversations.', 'Un assistant utilisable sans connaître SQL, qui répond avec les bons chiffres, refuse toute écriture en base et peut tourner entièrement hors ligne.', 'Empêcher un LLM de modifier la base, grâce à une validation stricte avant exécution, et obtenir du SQL fiable avec un petit modèle local.'),
('smecofarm-edge-ai', 'SmEcoFarm : ferme intelligente sur Raspberry Pi (Edge AI)', 'ia', 'Un Raspberry Pi détecte les oiseaux et les maladies des tomates par vision, surveille l''entrepôt et alerte en cas d''incendie, sans Internet.', 'Prototype scolaire où un seul Raspberry Pi 4 gère deux stations. Au champ : détection d''oiseaux, chassés par un buzzer, et diagnostic de 10 maladies de la tomate. À l''entrepôt : conservation des récoltes et sécurité incendie. Les modèles tournent sur l''appareil, sans connexion.', '/images/projects/smecofarm-edge-ai.svg', '["Python", "TensorFlow Lite", "EfficientDet-Lite0", "MobileNetV2", "OpenCV", "Raspberry Pi", "Blynk"]'::jsonb, 'https://github.com/mysteriodataweb/SmEcoFarm', NULL, '2026-10', false, true, 'Les petites exploitations perdent une partie de leurs récoltes à cause des oiseaux, des maladies et d''une mauvaise conservation, sans avoir les moyens d''une surveillance permanente.', 'Modèles TensorFlow Lite embarqués (EfficientDet-Lite0 pour les oiseaux, MobileNetV2 pour les maladies), détection de flammes par la couleur, capteurs DHT11 et MQ-135, ventilateur piloté par relais avec hystérésis, tableau de bord Blynk, alertes Gmail avec photo et démarrage automatique au boot.', 'Un aigle détecté à 84 % de confiance, sans aucune fausse alerte sur 6 photos sans oiseau. La logique métier se teste sans matériel grâce à 27 tests automatiques.', 'Faire tourner plusieurs modèles de vision sur un Raspberry Pi et composer avec les limites du matériel : le DHT11 ne mesure pas au-delà de 80 % d''humidité, donc la règle « humidité trop haute » est prête mais désactivée.'),
('gaalbrain-evaluation-socratique', 'GaAlBrain : évaluer la compréhension par questionnement socratique', 'ia', 'Un LLM pose des questions socratiques sur un concept pour mesurer ce que l''élève a vraiment compris, avec un suivi pour l''enseignant.', 'Au lieu d''un QCM, l''élève dialogue avec une IA qui l''interroge à la manière de Socrate. Chaque session produit des scores par concept, un score d''intégrité et un rapport ; l''enseignant suit sa classe depuis un tableau de bord.', '/images/projects/gaalbrain-evaluation-socratique.svg', '["TypeScript", "Express", "Groq", "React", "TanStack", "Tailwind CSS"]'::jsonb, 'https://github.com/mysteriodataweb/GaAlBrain-AI', NULL, '2026-05', false, true, 'Un QCM mesure mal la compréhension réelle et se contourne facilement, mais un enseignant n''a pas le temps d''interroger chaque élève à l''oral.', 'Backend Express en TypeScript avec le SDK Groq pour générer les questions, et une solution de repli locale si la génération échoue. Sessions, scores par concept, rapports et import de supports de cours ; interface React (TanStack) avec un espace élève et un espace enseignant.', 'Un MVP avec sessions d''évaluation, évolution de la compréhension par concept, score d''intégrité sur 30 jours et vue de l''enseignant élève par élève.', 'Obtenir du LLM des questions exploitables dans un format stable : extraction et normalisation du JSON renvoyé, et repli automatique quand la réponse est inutilisable.'),
('fake-news-detection-nlp', 'Détection de fake news par NLP', 'ia', 'Classification d''articles vrais ou faux par traitement du langage, complétée par une analyse des thèmes (LDA).', 'Comparaison de représentations du texte (sac de mots, TF-IDF) et de classifieurs (régression logistique, Naive Bayes, SVM linéaire) sur le jeu Kaggle Fake and Real News, puis modélisation des thèmes avec LDA.', '/images/projects/fake-news-detection-nlp.svg', '["Python", "NLTK", "scikit-learn", "Jupyter"]'::jsonb, 'https://github.com/mysteriodataweb/NLP_Project_Fake_News_Detection', NULL, '2026-05', false, true, 'Les fausses informations circulent plus vite que leur vérification. Un premier filtre automatique aide à choisir quels contenus vérifier en priorité.', 'Fusion des jeux Fake et True, prétraitement du texte avec NLTK (minuscules, ponctuation, mots vides), représentations BoW et TF-IDF, entraînement et comparaison de trois classifieurs, puis LDA pour comprendre les sujets dominants.', '99 % d''accuracy sur 8 837 articles de test avec la régression logistique et le SVM, contre 93 % pour Naive Bayes.', 'Un score aussi élevé appelle à la prudence : le modèle peut s''appuyer sur le style propre à chaque source du jeu de données plutôt que sur le fond, ce qui limite sa généralisation.'),
('fraud-detection-kafka', 'Détection de fraude bancaire en temps réel avec Kafka', 'data-engineering', 'Les transactions passent par Kafka ; un consumer Java interroge une API de machine learning qui renvoie la décision fraude ou légitime.', 'Un producer Python envoie les transactions sur Kafka, un consumer Java les consomme et appelle une API FastAPI qui sert un modèle Random Forest. L''API renvoie la probabilité de fraude et la décision.', '/images/projects/fraud-detection-kafka.svg', '["Python", "scikit-learn", "FastAPI", "Apache Kafka", "Java", "Maven"]'::jsonb, 'https://github.com/mysteriodataweb/fraud_detection_streaming_Kafka', NULL, '2026-09', false, true, 'Une fraude doit être bloquée au moment de la transaction, pas lors d''un contrôle après coup. Les fraudes sont très rares : 492 sur 284 807 transactions (0,17 %) dans le jeu de données Kaggle utilisé.', 'Exploration et entraînement d''un Random Forest (scikit-learn), choix du seuil de décision en comparant précision et rappel, mise à disposition du modèle via FastAPI, pipeline Kafka avec un producer Python et un consumer Java 21 (Maven).', 'Au seuil retenu de 0,40 : précision de 0,88, rappel de 0,83 et F1 de 0,85 sur la classe fraude. Le pipeline traite les transactions en continu.', 'Avec 0,17 % de fraudes, l''accuracy ne veut rien dire : un modèle qui ne détecte rien atteint 99,8 %. Le seuil a donc été choisi sur le compromis entre précision et rappel de la classe rare.'),
('africa-kpis-dashboard', 'Africa Dev Data Mart : indicateurs de développement africains', 'data-engineering', 'Pipeline qui extrait les indicateurs de la Banque mondiale pour 54 pays africains (2000-2024), les structure dans DuckDB et les expose dans un tableau de bord.', 'Un pipeline reproductible extrait, nettoie et charge dans un data mart DuckDB dix indicateurs de développement (PIB, accès à l''eau et à l''électricité, scolarisation, mortalité infantile, pauvreté…) pour tous les pays africains, puis alimente un tableau de bord web destiné aux décideurs.', '/images/projects/africa-kpis-dashboard.svg', '["Python", "pandas", "DuckDB", "API World Bank", "Plotly", "Next.js", "TypeScript"]'::jsonb, 'https://github.com/mysteriodataweb/African_Countries_KPIS_Analysis', NULL, '2026-07', false, true, 'Les indicateurs de développement existent, mais ils sont dispersés et difficiles à comparer d''un pays à l''autre. Un décideur a besoin d''une vue propre et comparable.', 'Extraction depuis l''API World Bank v2 avec mise en cache, référentiel des pays africains (agrégats régionaux exclus), transformation et nettoyage en Python, chargement dans DuckDB, visualisations Plotly, export JSON vers un tableau de bord Next.js statique et documentation méthodologique.', 'Un data mart couvrant 54 pays sur 25 ans, et un tableau de bord avec grille d''indicateurs, courbes multi-pays, carte choroplèthe et comparaison de deux indicateurs.', 'Gérer les valeurs manquantes et les séries incomplètes selon les pays et les années, tout en gardant le pipeline reproductible de bout en bout.'),
('ftth-prediction-togo', 'Prédiction de l''accès à la fibre optique au Togo', 'data-science', 'Modèle qui prédit l''accès potentiel des ménages togolais à la fibre (FTTH) à partir de données socio-démographiques et géospatiales.', 'À partir de 30 558 ménages et 46 variables, le modèle estime la probabilité d''accès à la fibre de chaque ménage et fait ressortir les déterminants de la connectivité, pour orienter le déploiement de l''infrastructure.', '/images/projects/ftth-prediction-togo.svg', '["Python", "pandas", "scikit-learn", "XGBoost", "Jupyter"]'::jsonb, 'https://github.com/mysteriodataweb/ACDS_FBER_ACCESS_PRED', NULL, '2025-12', false, true, 'Projet réalisé dans le cadre du challenge ACDS 2025 : repérer les ménages et les zones prioritaires pour le déploiement de la fibre optique au Togo.', 'Analyse exploratoire, préparation de 46 variables (logement, équipement, caractéristiques géospatiales), comparaison de plusieurs modèles dont Random Forest et XGBoost, évaluation en AUC, F1, précision et rappel, puis export du meilleur modèle et des prédictions.', 'Random Forest retenu : AUC de 0,88 et F1 de 0,84 sur le jeu de test, avec un rappel de 0,91, donc peu de ménages éligibles oubliés.', 'Traiter un jeu de données de 2,2 Go sur une machine personnelle, et surveiller l''écart entre l''entraînement (AUC 0,98) et le test (0,88) pour limiter le surapprentissage.'),
('ml-portfolio-projets', 'Collection de 10 projets de machine learning', 'data-science', 'Dix projets documentés : NLP, deep learning, séries temporelles, régression, recherche sémantique et LLM.', 'Un dépôt organisé qui couvre le cycle complet du machine learning sur dix cas : détection de fake news, churn avec TensorFlow, réduction de dimension par ACP, prévision boursière ARIMA/GARCH, recherche sémantique avec Pinecone, génération de texte avec des LLM et régression en R.', '/images/projects/ml-portfolio-projets.svg', '["Python", "scikit-learn", "TensorFlow", "Keras", "statsmodels", "Hugging Face", "LangChain", "Pinecone", "R"]'::jsonb, 'https://github.com/mysteriodataweb/ML_Datascience_AI_Projects', NULL, '2026-09', false, true, 'Rassembler au même endroit des projets courts et documentés qui montrent la maîtrise des techniques fondamentales du machine learning.', 'Un notebook documenté par projet, une structure commune, un environnement reproductible et une intégration continue avec GitHub Actions.', '10 projets prêts à être relus ou réutilisés, dont une détection de fake news à 99,3 % d''accuracy et une recherche sémantique pondérée avec Sentence Transformers et Pinecone.', 'Garder une documentation homogène et des projets reproductibles malgré des domaines et des bibliothèques très différents.'),
('music-genre-classification-pca', 'Classification de genres musicaux par ACP', 'data-science', 'Réduction de dimension par ACP puis régression logistique pour prédire le genre des morceaux qui n''en ont pas.', 'Sur 1 000 morceaux décrits par des variables numériques, l''ACP réduit la dimension en conservant au moins 80 % de la variance, puis une régression logistique prédit le genre des morceaux non étiquetés.', '/images/projects/music-genre-classification-pca.svg', '["Python", "pandas", "scikit-learn", "Matplotlib", "Seaborn"]'::jsonb, 'https://github.com/mysteriodataweb/Music_classification_PCA', NULL, '2026-01', false, true, 'Une partie des morceaux du jeu de données n''a pas de genre renseigné : il faut le prédire à partir de leurs caractéristiques audio.', 'Exploration et analyse des corrélations, standardisation, ACP (au moins 80 % de variance conservée), régression logistique avec et sans ACP pour mesurer l''apport de la réduction de dimension.', 'Un pipeline complet qui attribue un genre aux morceaux non étiquetés et compare les performances avec et sans ACP.', 'Choisir le nombre de composantes : assez pour garder l''information, assez peu pour réduire le bruit et la colinéarité.'),
('simulation-pont-marin', 'Simulation mécanique d''un pont marin', 'data-science', 'Application Streamlit qui calcule et visualise en 3D les contraintes d''un pont marin soumis au vent, aux vagues et aux séismes.', 'On règle la géométrie du pont (tablier, piles) et les aléas (vent, profondeur d''eau, accélération sismique) ; l''application calcule les efforts selon la mécanique des milieux continus et affiche la structure en 3D.', '/images/projects/simulation-pont-marin.svg', '["Python", "Streamlit", "NumPy", "Plotly"]'::jsonb, 'https://github.com/mysteriodataweb/Bridge_simulation', NULL, '2026-02', false, true, 'Projet de mécanique des milieux continus : rendre visibles les effets des charges environnementales sur un ouvrage en mer.', 'Application Streamlit avec réglages en barre latérale, calculs physiques avec NumPy (module d''Young, densités du béton et de l''eau de mer, limite d''élasticité) et rendu 3D interactif avec Plotly.', 'Un outil interactif qui montre en direct comment chaque paramètre fait évoluer les contraintes et le risque de dépasser la limite du matériau.', 'Traduire des formules de mécanique en un modèle de calcul simple, rapide et lisible à l''écran.'),
('dataviz-energie-afrique', 'DataViz : production d''électricité par pays', 'data-analyst', 'Collecte des données de production électrique par web scraping, nettoyage en Python et tableau de bord Power BI.', 'Un script de scraping récupère les données de production d''électricité publiées par Our World in Data, un notebook les nettoie et les prépare, et un tableau de bord Power BI permet d''analyser la production par pays et par source.', '/images/projects/dataviz-energie-afrique.svg', '["Python", "Selenium", "BeautifulSoup", "pandas", "Power BI", "Excel"]'::jsonb, 'https://github.com/mysteriodataweb/Dataviz_africitizen_project', NULL, '2025-11', false, true, 'Projet réalisé à Centrale Casablanca : analyser la production d''électricité par pays et par source à partir de données publiques.', 'Module de scraping réutilisable (Selenium, Helium, BeautifulSoup) appelé depuis un notebook, nettoyage avec pandas et export Excel, puis modélisation et visualisation dans Power BI.', 'Un jeu de données propre et un tableau de bord Power BI interactif sur la production électrique.', 'Transformer un tableau web dynamique en jeu de données exploitable et cohérent d''un pays à l''autre.'),
('innopro-gestion-maintenance', 'InnoFaso : gestion de la maintenance et de la production', 'web-app', 'Application web d''entreprise pour gérer formulaires de maintenance, production, stocks et alertes, avec génération de formulaires par IA.', 'Application fullstack réalisée en binôme : formulaires configurables par glisser-déposer, circuit de soumission et de validation, stocks de matières premières, alertes automatiques et exports Excel, avec une génération de formulaires assistée par un LLM.', '/images/projects/innopro-gestion-maintenance.svg', '["Node.js", "Express", "PostgreSQL", "React", "Vite", "Tailwind CSS", "JWT", "ExcelJS", "Groq"]'::jsonb, 'https://github.com/mysteriodataweb/innopro', NULL, '2026-06', false, true, 'Une unité de production suivait sa maintenance et sa production sur papier et dans des tableurs, sans alerte en cas de panne critique ou de stock bas.', 'API Node.js/Express et PostgreSQL (13 migrations), authentification JWT avec jeton de rafraîchissement, constructeur de formulaires (texte, nombre, date, signature, photo…), suppression réversible, export Excel (ExcelJS) et génération de formulaires via Groq (Llama 3.3 70B). Interface React, Vite et Tailwind.', 'Deux modules opérationnels, maintenance et production : soumission et validation des formulaires, historique filtrable, alertes (formulaire en retard, stock bas, panne critique) et exports Excel.', 'Rendre les formulaires entièrement configurables sans redéployer l''application, et fusionner le travail de deux développeurs sur une même base de code.'),
('cap-assistant-planification', 'Cap : assistant de planification de journée', 'web-app', 'Application web installable qui aide à planifier une journée réaliste et à avancer vers ses objectifs. En cours de développement.', 'Application Next.js installable sur téléphone (PWA) : connexion par code reçu par e-mail, objectifs, plan du jour découpé en blocs, bilans et notifications, sur une base Supabase protégée par des règles de sécurité testées.', '/images/projects/cap-assistant-planification.svg', '["Next.js", "TypeScript", "Supabase", "PostgreSQL", "Vitest", "Playwright", "GitHub Actions"]'::jsonb, 'https://github.com/mysteriodataweb/persoapp', NULL, '2026-10', false, true, 'Les listes de tâches trop ambitieuses découragent. L''idée : planifier une journée faisable et suivre ce qui avance vraiment.', 'Next.js (App Router) et TypeScript, Supabase (PostgreSQL, connexion par code à usage unique, sécurité au niveau des lignes), migrations versionnées, service worker et notifications push, tests unitaires Vitest, tests de bout en bout Playwright et intégration continue GitHub Actions.', 'Le socle est en place : authentification, schéma de données (objectifs, plans, blocs, bilans, apprentissages), règles de sécurité testées et pipeline d''intégration continue.', 'Tester la sécurité directement dans la base, avec des tests dédiés aux règles d''accès, et pas seulement à travers l''interface.'),
('plateforme-edtech', 'Plateforme EdTech : API de cours, quiz et assistant IA', 'web-app', 'API d''une plateforme d''apprentissage pour étudiants d''Afrique francophone : cours, ressources, QCM progressifs et assistant IA.', 'Backend d''un SaaS EdTech pensé pour le mobile et les réseaux lents : suivi des cours, ressources associées, QCM dont la difficulté progresse, assistant IA qui répond dans le contexte du cours, et suivi de la progression.', '/images/projects/plateforme-edtech.svg', '["Express", "TypeScript", "Supabase", "PostgreSQL"]'::jsonb, 'https://github.com/mysteriodataweb/plateformedtech', NULL, '2026-09', false, true, 'Les étudiants d''Afrique francophone étudient souvent sur téléphone, avec une connexion instable, et manquent d''accompagnement entre les cours.', 'API Express en TypeScript ; Supabase pour la base PostgreSQL, l''authentification et la sécurité au niveau des lignes ; modules cours, ressources, quiz, assistant IA et progression ; endpoints documentés.', 'Une API documentée qui couvre l''ensemble des modules, avec un contrôle d''accès appliqué directement dans la base.', 'Concevoir une API légère pour des réseaux lents et protéger les données de chaque étudiant au niveau de la base.'),
('agblenuku-approvisionnement-agricole', 'Agblenuku : plateforme d''approvisionnement agricole', 'web-app', 'API qui met en relation les producteurs agricoles locaux avec les restaurants, hôtels et commerces de la ville.', 'Backend d''une plateforme où un restaurant exprime un besoin, trouve des producteurs disponibles, passe commande et suit son approvisionnement. L''architecture est prévue pour accueillir ensuite recommandations, prévision de la demande et optimisation logistique.', '/images/projects/agblenuku-approvisionnement-agricole.svg', '["NestJS", "TypeScript", "PostgreSQL", "Prisma", "Supabase", "JWT", "Swagger"]'::jsonb, 'https://github.com/mysteriodataweb/agblenuku', NULL, '2026-08', false, true, 'Les producteurs locaux ont du mal à vendre directement aux professionnels de la ville, qui manquent eux-mêmes de visibilité sur l''offre disponible.', 'API REST NestJS modulaire en TypeScript, PostgreSQL avec Prisma, authentification JWT et rôles (agriculteur, client professionnel, administrateur), images sur Supabase Storage, validation des entrées et documentation Swagger.', 'Un MVP backend : profils producteurs, catalogue de produits, commandes et suivi, avec une API documentée.', 'Poser dès le MVP un modèle de données assez propre pour ajouter plus tard les fonctions d''IA sans tout reprendre.'),
('campusfix', 'CampusFix : signalement des pannes sur un campus', 'web-app', 'Plateforme pour signaler une panne sur le campus via un QR code et suivre sa résolution jusqu''à l''intervention.', 'Étudiants et personnel signalent un problème (salle, équipement) en scannant un QR code ; les responsables suivent, attribuent et clôturent les demandes depuis un tableau de bord.', '/images/projects/campusfix.svg', '["Next.js", "TypeScript", "Express", "Tailwind CSS"]'::jsonb, 'https://github.com/mysteriodataweb/campusfix-platform', NULL, '2026-03', false, true, 'Sur un campus, les pannes sont signalées à l''oral ou par e-mail : elles se perdent et ne sont pas suivies.', 'API Express en TypeScript (authentification, lieux, signalements, journal, espace responsable) et interface Next.js avec génération de QR codes et graphiques.', 'Un circuit complet, du signalement à la résolution, avec historique et vue d''ensemble pour les responsables.', 'Rendre le signalement assez simple pour être fait en quelques secondes depuis un téléphone.'),
('portfolio-kwami-dev', 'Ce portfolio (kwami.dev)', 'web-app', 'Site fullstack avec espace d''administration : projets, blog, CV généré en PDF et messages de contact.', 'Le site que vous consultez : une interface React qui lit une API Express, avec un espace d''administration pour modifier projets, articles, compétences et profil sans toucher au code.', '/images/projects/portfolio-kwami-dev.svg', '["React", "TypeScript", "Vite", "Tailwind CSS", "Node.js", "Express", "PostgreSQL", "Supabase"]'::jsonb, 'https://github.com/mysteriodataweb/portfoliofrontend', NULL, '2026-10', false, true, 'Un portfolio statique devient vite obsolète ; il fallait pouvoir mettre à jour le contenu en quelques clics.', 'Interface React, TypeScript, Vite et Tailwind déployée sur Vercel ; API Express (dépôt portfoliobackend) déployée sur Render avec PostgreSQL (Supabase) ; administration protégée par JWT ; CV généré en PDF ; formulaire de contact avec notification par e-mail.', 'Un site administrable de bout en bout, durci côté sécurité : limitation des tentatives de connexion, échappement des contenus, protection anti-spam.', 'Garder un seul espace pour le public et l''administration sans exposer les fonctions d''édition aux visiteurs.'),
('gestion-2ie', 'Gestion 2iE : application de gestion scolaire', 'web-app', 'Application web de gestion des ressources d''un établissement, avec authentification.', 'Application React et Express qui permet de se connecter et de gérer les ressources d''un établissement : création, consultation, modification et suppression.', '/images/projects/gestion-2ie.svg', '["React", "Vite", "Tailwind CSS", "Node.js", "Express"]'::jsonb, 'https://github.com/mysteriodataweb/Gestion_etudiants', NULL, '2026-05', false, true, 'Projet de cours pour mettre en place une architecture web complète, de l''interface jusqu''à l''API.', 'Interface React, Vite et Tailwind ; API Express avec des routes d''authentification et de ressources, et des modèles séparés.', 'Une application fonctionnelle de bout en bout : connexion et gestion des ressources.', 'Structurer proprement l''API (routes et modèles) et gérer l''authentification entre l''interface et le serveur.'),
('blog-api-rest', 'API REST de blog (Node.js, MySQL, JWT)', 'web-app', 'Backend d''un blog : articles, utilisateurs et authentification JWT, avec une architecture en couches.', 'API REST organisée en routes, contrôleurs, modèles et middlewares, avec authentification JWT, mots de passe hachés, en-têtes de sécurité et un fichier de tests des endpoints.', '/images/projects/blog-api-rest.svg', '["Node.js", "Express", "MySQL", "JWT", "bcrypt"]'::jsonb, 'https://github.com/mysteriodataweb/Backend_article_BIAM', NULL, '2026-04', false, true, 'Projet de cours : concevoir le backend d''une application de blog proprement structuré.', 'Node.js et Express, MySQL via mysql2, JWT, bcrypt, Helmet et CORS, schéma SQL versionné et requêtes de test au format REST Client.', 'Une API complète pour gérer articles et utilisateurs, prête à être branchée sur une interface.', 'Séparer clairement les responsabilités (routes, logique métier, accès aux données) pour garder le code lisible et testable.'),
('blogmag', 'BlogMag : magazine en ligne', 'web-app', 'Blog au format magazine en Next.js, avec pages d''articles, création d''article et choix d''ergonomie documentés.', 'Magazine en ligne avec une page d''accueil éditoriale, un carrousel, des pages d''articles et un formulaire de création, accompagné d''un document qui justifie les choix d''ergonomie.', '/images/projects/blogmag.svg', '["Next.js", "TypeScript", "Tailwind CSS", "shadcn/ui"]'::jsonb, 'https://github.com/mysteriodataweb/BlogMag', NULL, '2026-03', false, true, 'Projet de cours centré sur l''expérience utilisateur d''un média en ligne.', 'Next.js, TypeScript, Tailwind CSS et composants shadcn/ui, carrousel Embla, thème clair et sombre.', 'Un site magazine complet et un document qui explique les choix d''ergonomie.', 'Hiérarchiser beaucoup de contenus sur une même page d''accueil sans la surcharger.'),
('2ieapp', '2ieApp : site web avec espace membre', 'web-app', 'Site Next.js avec pages d''accueil, à propos et contact, inscription et connexion.', 'Site multi-pages en Next.js avec un espace public (accueil, à propos, contact) et un espace d''authentification (inscription, connexion) qui partagent leurs mises en page.', '/images/projects/2ieapp.svg', '["Next.js", "TypeScript", "Tailwind CSS"]'::jsonb, 'https://github.com/mysteriodataweb/2ie_Alfred_BIAM', NULL, '2026-02', false, true, 'Projet de cours pour prendre en main Next.js et son système de routes.', 'Next.js (App Router) avec des groupes de routes pour séparer l''authentification des pages publiques, composants réutilisables et Tailwind CSS.', 'Un site responsive multi-pages avec des parcours d''inscription et de connexion.', 'Organiser les routes et les mises en page partagées entre les deux espaces.'),
('medicare-portail-patient', 'MediCare : portail patient', 'web-app', 'Interface de portail patient : rendez-vous, dossier médical et conseils de santé.', 'Interface Next.js d''un portail où le patient consulte ses rendez-vous, accède à son dossier médical et reçoit des conseils de santé.', '/images/projects/medicare-portail-patient.svg', '["Next.js", "TypeScript", "Tailwind CSS", "shadcn/ui"]'::jsonb, 'https://github.com/mysteriodataweb/MEDICARE', NULL, '2025-08', false, true, 'Rassembler en un seul endroit les informations dont un patient a besoin entre deux consultations.', 'Next.js et TypeScript, Tailwind CSS et shadcn/ui, composants dédiés (cartes de rendez-vous, onglets de filtre, conseils santé).', 'Une interface claire et responsive, prête à être reliée à un backend.', 'Présenter des informations médicales de façon rassurante et lisible.'),
('baobab-rising', 'Baobab Rising : site de présentation d''un discours', 'web-app', 'Site vitrine bilingue qui présente le discours « Baobab Rising » sur la jeunesse africaine, avec sa vidéo.', 'Site en français et en anglais qui présente le discours « Baobab Rising : nourrir l''avenir grâce à la jeunesse africaine », avec la vidéo et les messages clés.', '/images/projects/baobab-rising.svg', '["React", "TypeScript", "Vite", "Tailwind CSS"]'::jsonb, 'https://github.com/mysteriodataweb/BaobabSpeakyourMind', NULL, '2025-06', false, true, 'Donner une vitrine en ligne à une prise de parole sur la jeunesse africaine.', 'React, TypeScript et Vite, Tailwind CSS, contenu bilingue et lecteur vidéo.', 'Un site vitrine en deux langues, simple à partager.', 'Porter un message fort avec une mise en page sobre, dans deux langues.'),
('togoporc', 'TogoPorc : vitrine d''un élevage porcin au Togo', 'web-app', 'Premier site web : vitrine en ligne pour la vente de porcs d''élevage au Togo.', 'Site statique qui présente l''offre d''un élevage porcin au Togo : races adaptées au climat local, sélection pour l''élevage et la reproduction, et prise de contact.', '/images/projects/togoporc.svg', '["HTML", "CSS", "JavaScript"]'::jsonb, 'https://github.com/mysteriodataweb/github/tree/master/entreprise_porc_project', NULL, '2025-04', false, true, 'Un élevage local voulait être visible en ligne et présenter ses animaux.', 'HTML, CSS et JavaScript, sans framework.', 'Une vitrine en ligne responsive, mon premier projet web.', 'Apprendre les bases de l''intégration web et de la mise en page responsive.')
ON CONFLICT (slug) DO UPDATE SET
  title = EXCLUDED.title,
  category = EXCLUDED.category,
  short_description = EXCLUDED.short_description,
  full_description = EXCLUDED.full_description,
  image = CASE WHEN projects.image LIKE '%supabase%' THEN projects.image ELSE EXCLUDED.image END,
  tech_stack = EXCLUDED.tech_stack,
  github_url = EXCLUDED.github_url,
  demo_url = COALESCE(projects.demo_url, EXCLUDED.demo_url),
  date = EXCLUDED.date,
  featured = EXCLUDED.featured,
  published = true,
  archived = false,
  archived_at = NULL,
  context = EXCLUDED.context,
  approach = EXCLUDED.approach,
  results = EXCLUDED.results,
  challenges = EXCLUDED.challenges,
  updated_at = NOW();

COMMIT;
